import{a as e,c as t,d as n,l as r,m as i,p as a,s as o,t as s,u as c}from"./app-BsOuDHI-.js";var l=JSON.parse(`{"path":"/documentation/quartz-4.x/tutorial/querying-jobs-and-triggers.html","title":"Querying Jobs and Triggers","lang":"en-US","frontmatter":{"title":"Querying Jobs and Triggers"},"git":{"updatedTime":1788441191000,"contributors":[{"name":"Marko Lahma","username":"","email":"marko.lahma@gmail.com","commits":1},{"name":"Claude Fable 5.1","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"8dee9f767ead84b6e47c023533864d1d3e3178ae","time":1788441191000,"email":"marko.lahma@gmail.com","author":"Marko Lahma","message":"The release post carries the day 4.0.0 shipped","coAuthors":[{"name":"Claude Fable 5.1","email":"noreply@anthropic.com"}]}]},"filePathRelative":"documentation/quartz-4.x/tutorial/querying-jobs-and-triggers.md"}`),u={name:`querying-jobs-and-triggers.md`};function d(s,l,u,d,f,p){let m=a(`RouteLink`);return n(),o(`div`,null,[l[31]||=t(`<p>Sooner or later something has to answer &quot;what is scheduled?&quot; — an admin screen, a health endpoint, a support script, a migration that has to find every trigger it broke. In 3.x that meant a handful of listing members that each returned everything they could find. In 4.x it is one query family: you describe what you want, ask for a page of it, and get back headers you can render.</p><h2 id="why-listings-became-queries" tabindex="-1"><a class="header-anchor" href="#why-listings-became-queries"><span>Why listings became queries</span></a></h2><p>3.x answered every one of these questions with a listing member of its own, and every one of them enumerated. <code>GetTriggerKeys</code> returned keys, so a UI that wanted a trigger&#39;s state fetched each trigger separately — one round trip per row. <code>GetNumberOfJobs</code> existed because counting through <code>GetJobKeys</code> meant loading every key. Nothing paged, so a scheduler with fifty thousand triggers had no safe way to show the first fifty.</p><p>Six query members replace them, and they all work the same way:</p><table><thead><tr><th>Query</th><th>Returns</th><th>Selects</th></tr></thead><tbody><tr><td><code>QueryJobs(JobQuery)</code></td><td><code>PagedResult&lt;JobHeader&gt;</code></td><td>jobs</td></tr><tr><td><code>QueryTriggers(TriggerQuery)</code></td><td><code>PagedResult&lt;TriggerHeader&gt;</code></td><td>triggers</td></tr><tr><td><code>QueryJobGroups(JobGroupQuery)</code></td><td><code>PagedResult&lt;JobGroup&gt;</code></td><td>job groups</td></tr><tr><td><code>QueryTriggerGroups(TriggerGroupQuery)</code></td><td><code>PagedResult&lt;TriggerGroup&gt;</code></td><td>trigger groups</td></tr><tr><td><code>QueryCalendarNames(CalendarQuery)</code></td><td><code>PagedResult&lt;string&gt;</code></td><td>calendar names</td></tr><tr><td><code>QueryFireInstances(FireInstanceQuery)</code></td><td><code>PagedResult&lt;FireInstance&gt;</code></td><td>firings in flight</td></tr></tbody></table><p>The same six are on <code>IJobStore</code>, with the same shapes, so a custom store implements the listing story once.</p><h2 id="headers-not-entities" tabindex="-1"><a class="header-anchor" href="#headers-not-entities"><span>Headers, not entities</span></a></h2><p>A listing hands back a <em>header</em>: enough to render a row, and nothing that costs a second read.</p><p><code>JobHeader</code> carries <code>Key</code>, <code>Description</code>, <code>JobTypeName</code>, <code>Durable</code>, <code>ConcurrentExecutionDisallowed</code>, <code>PersistJobDataAfterExecution</code> and <code>RequestsRecovery</code>.</p><p><code>TriggerHeader</code> carries <code>Key</code>, <code>JobKey</code>, <code>Description</code>, <code>TriggerType</code>, <code>State</code>, <code>StartTimeUtc</code>, <code>EndTimeUtc</code>, <code>NextFireTimeUtc</code>, <code>PreviousFireTimeUtc</code>, <code>CalendarName</code>, <code>Priority</code> and <code>ExecutionGroup</code>.</p><p>Neither carries a <code>JobDataMap</code>. Job data is a blob in the persistent store, and deserializing one per row would make every listing pay for data no list screen shows. When you need the whole object, fetch it — see <a href="#from-a-page-to-full-detail">from a page to full detail</a> below.</p><p><code>TriggerHeader.State</code> is the one to notice: in 3.x a trigger listing gave you keys and you called <code>GetTriggerState</code> per key to colour the rows. The state is in the row now, computed by the store as part of the same query.</p><h2 id="filtering" tabindex="-1"><a class="header-anchor" href="#filtering"><span>Filtering</span></a></h2><p>Every query is a record with init-only filter properties. A null filter matches everything, and the filters that are set combine with <strong>AND</strong>:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>TriggerHeader<span class="token punctuation">&gt;</span></span> page <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryTriggers</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TriggerQuery</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Group <span class="token operator">=</span> GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupStartsWith</span><span class="token punctuation">(</span><span class="token string">&quot;reporting-&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    State <span class="token operator">=</span> TriggerState<span class="token punctuation">.</span>Error<span class="token punctuation">,</span></span>
<span class="line">    Take <span class="token operator">=</span> <span class="token number">50</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>Query</th><th>Filters</th></tr></thead><tbody><tr><td><code>JobQuery</code></td><td><code>Group</code> (<code>GroupMatcher&lt;JobKey&gt;</code>), <code>Name</code> (<code>NameMatcher&lt;JobKey&gt;</code>)</td></tr><tr><td><code>TriggerQuery</code></td><td><code>Group</code>, <code>Name</code>, <code>Job</code> (<code>JobKey</code>), <code>CalendarName</code> (<code>string</code>), <code>State</code> (<code>TriggerState?</code>)</td></tr><tr><td><code>JobGroupQuery</code> / <code>TriggerGroupQuery</code></td><td><code>Name</code> (<code>NameMatcher</code>), <code>Paused</code> (<code>bool?</code>)</td></tr><tr><td><code>CalendarQuery</code></td><td><code>Name</code> (<code>NameMatcher</code>)</td></tr><tr><td><code>FireInstanceQuery</code></td><td><code>TriggerGroup</code>, <code>TriggerName</code>, <code>Job</code>, <code>SchedulerInstanceId</code>, <code>State</code></td></tr></tbody></table><p>A filter is named for what it selects on: <code>Group</code> and <code>Name</code> are the result&#39;s own identity, and a filter on something the result merely refers to carries that thing&#39;s name — <code>Job</code>, <code>CalendarName</code>, <code>SchedulerInstanceId</code>. That is why <code>FireInstanceQuery</code> alone says <code>TriggerGroup</code> and <code>TriggerName</code>: a firing is identified by a fire instance id rather than by a key, so the trigger it belongs to is a reference like any other, and an unqualified <code>Name</code> would leave you guessing whether it meant the trigger&#39;s or the job&#39;s.</p><p>Every name filter is a matcher of one family. <code>GroupMatcher&lt;TKey&gt;</code> and <code>NameMatcher&lt;TKey&gt;</code> have the four shapes you would expect — <code>GroupEquals</code>/<code>GroupStartsWith</code>/<code>GroupEndsWith</code>/<code>GroupContains</code> and the <code>Name*</code> counterparts — and <code>NameMatcher</code>, the arity-free twin, is the same four over a name that belongs to no key: a calendar&#39;s, a group&#39;s. <code>GroupMatcher&lt;TKey&gt;.AnyGroup()</code> exists for the members that take a matcher and not a null, such as <code>PauseTriggerGroups</code>; a query filter is nullable and null already means every name, so there is no &quot;any&quot; spelling to learn here.</p><p>The matcher text is a literal, not a pattern: a group named <code>50%</code> is selected by <code>GroupStartsWith(&quot;50%&quot;)</code>, and the store escapes the wildcard on its way into SQL.</p><h3 id="matchers-as-a-vocabulary" tabindex="-1"><a class="header-anchor" href="#matchers-as-a-vocabulary"><span>Matchers as a vocabulary</span></a></h3><p><code>Matchers</code> is the entry point when you would rather not spell the generic argument, and it is where the combinators live:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">IMatcher<span class="token punctuation">&lt;</span>JobKey<span class="token punctuation">&gt;</span></span> notArchived <span class="token operator">=</span> Matchers<span class="token punctuation">.</span><span class="token generic-method"><span class="token function">Group</span><span class="token generic class-name"><span class="token punctuation">&lt;</span>JobKey<span class="token punctuation">&gt;</span></span></span><span class="token punctuation">(</span>StringOperator<span class="token punctuation">.</span>StartsWith<span class="token punctuation">,</span> <span class="token string">&quot;archive-&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Not</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">IMatcher<span class="token punctuation">&lt;</span>TriggerKey<span class="token punctuation">&gt;</span></span> either <span class="token operator">=</span> Matchers<span class="token punctuation">.</span><span class="token function">Key</span><span class="token punctuation">(</span>triggerKey<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Or</span><span class="token punctuation">(</span>Matchers<span class="token punctuation">.</span><span class="token function">AllTriggers</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>Matchers.AllJobs()</code> and <code>Matchers.AllTriggers()</code> return <code>EverythingMatcher&lt;TKey&gt;</code>, <code>Matchers.Key(key)</code> matches one key exactly, and <code>And</code>, <code>Or</code> and <code>Not</code> are extension methods on <code>IMatcher&lt;TKey&gt;</code>.</p><p>The combinators are for the <em>listener</em> matchers on <code>IListenerManager</code> and <code>IQuartzBuilder</code>, which evaluate in memory. The query filters are typed to <code>GroupMatcher&lt;TKey&gt;</code> and <code>NameMatcher&lt;TKey&gt;</code> specifically, because those are the two shapes a job store can translate to SQL.</p><h2 id="paging" tabindex="-1"><a class="header-anchor" href="#paging"><span>Paging</span></a></h2><p>Results are ordered by group and then name, ordinal, on every store. That is what makes a page deterministic: <code>Skip</code> and <code>Take</code> are offsets into one stable ordering, so page 3 is page 3 whichever node answers.</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>JobHeader<span class="token punctuation">&gt;</span></span> page <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryJobs</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">JobQuery</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Skip <span class="token operator">=</span> <span class="token punctuation">(</span>pageNumber <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">*</span> pageSize<span class="token punctuation">,</span></span>
<span class="line">    Take <span class="token operator">=</span> pageSize<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>Take</code> defaults to <code>PagedQuery.DefaultTake</code>, which is <strong>250</strong>. An unpaged call therefore cannot accidentally materialize a hundred thousand rows; <code>PagedResult&lt;T&gt;.HasMore</code> tells you whether anything was left out. Ask for everything explicitly:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">JobQuery</span> everything <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> Take <span class="token operator">=</span> PagedQuery<span class="token punctuation">.</span>All <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,29),e(`p`,null,[l[1]||=e(`code`,null,`PagedQuery.All`,-1),l[2]||=r(` is `,-1),l[3]||=e(`code`,null,`int.MaxValue`,-1),l[4]||=r(`. It has a name because a call site that says `,-1),l[5]||=e(`code`,null,`int.MaxValue`,-1),l[6]||=r(` reads as an overflow guard rather than as a decision, and over HTTP the same thing is spelled `,-1),c(m,{to:`/documentation/quartz-4.x/packages/http-api.html#listing-endpoints-are-paged`},{default:i(()=>[...l[0]||=[e(`code`,null,`?take=all`,-1)]]),_:1}),l[7]||=r(`.`,-1)]),l[32]||=t(`<p><code>HasMore</code> is exact and effectively free — the stores read one row past <code>Take</code> to answer it. <code>TotalCount</code> is <code>null</code> unless you ask for it, because on a persistent store it costs a second query:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>TriggerHeader<span class="token punctuation">&gt;</span></span> page <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryTriggers</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TriggerQuery</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Take <span class="token operator">=</span> pageSize<span class="token punctuation">,</span></span>
<span class="line">    IncludeTotalCount <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name"><span class="token keyword">int</span></span> total <span class="token operator">=</span> page<span class="token punctuation">.</span>TotalCount<span class="token operator">!</span><span class="token punctuation">.</span>Value<span class="token punctuation">;</span>   <span class="token comment">// non-null because IncludeTotalCount was set</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="counting-without-rows" tabindex="-1"><a class="header-anchor" href="#counting-without-rows"><span>Counting without rows</span></a></h3><p><code>GetNumberOfJobs</code>, <code>GetNumberOfTriggers</code> and <code>GetNumberOfCalendars</code> are gone. A count is a query that asks for no rows:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>JobHeader<span class="token punctuation">&gt;</span></span> count <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryJobs</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">JobQuery</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Take <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">    IncludeTotalCount <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name"><span class="token keyword">int</span></span> jobCount <span class="token operator">=</span> count<span class="token punctuation">.</span>TotalCount<span class="token operator">!</span><span class="token punctuation">.</span>Value<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>Take = 0</code> is valid and returns an empty <code>Items</code>; the stores recognize the combination and run the count query alone. The same idiom counts anything the family can select — triggers in the error state, calendars whose name starts with a prefix, firings on one node.</p><h2 id="from-a-page-to-full-detail" tabindex="-1"><a class="header-anchor" href="#from-a-page-to-full-detail"><span>From a page to full detail</span></a></h2><p>A listing gives you headers. When the user opens a row, or a script needs the actual objects, fetch them by key in one round trip rather than in a loop:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">List<span class="token punctuation">&lt;</span>JobKey<span class="token punctuation">&gt;</span></span> keys <span class="token operator">=</span> page<span class="token punctuation">.</span>Items<span class="token punctuation">.</span><span class="token function">Select</span><span class="token punctuation">(</span>h <span class="token operator">=&gt;</span> h<span class="token punctuation">.</span>Key<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ToList</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">List<span class="token punctuation">&lt;</span>IJobDetail<span class="token punctuation">&gt;</span></span> details <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">GetJobDetails</span><span class="token punctuation">(</span>keys<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name">List<span class="token punctuation">&lt;</span>ITrigger<span class="token punctuation">&gt;</span></span> triggers <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">GetTriggers</span><span class="token punctuation">(</span>triggerKeys<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Keys that do not exist are simply absent from the result — a bulk fetch is not an existence check, and it does not throw for a key that has been deleted since the listing ran. <code>Exists(JobKey)</code> and <code>Exists(TriggerKey)</code> answer that question directly.</p><div class="hint-container warning"><p class="hint-container-title">Changed in 4.x</p><p><code>CheckExists</code> is now <code>Exists</code>, on both overloads.</p></div><h2 id="fire-instances-what-is-running-right-now" tabindex="-1"><a class="header-anchor" href="#fire-instances-what-is-running-right-now"><span>Fire instances: what is running right now</span></a></h2><p><code>GetCurrentlyExecutingJobs()</code> is gone. It could only ever describe the node that answered, it returned whole <code>IJobExecutionContext</code> objects, and it had no filter and no paging. <code>QueryFireInstances</code> replaces it, and because it is store-backed it covers the whole cluster on a persistent store:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>FireInstance<span class="token punctuation">&gt;</span></span> running <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryFireInstances</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">FireInstanceQuery</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    TriggerGroup <span class="token operator">=</span> GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span><span class="token string">&quot;reporting&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name">FireInstance</span> fire <span class="token keyword">in</span> running<span class="token punctuation">.</span>Items<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span><span class="token interpolation-string"><span class="token string">$&quot;</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">fire<span class="token punctuation">.</span>TriggerKey</span><span class="token punctuation">}</span></span><span class="token string"> on </span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">fire<span class="token punctuation">.</span>SchedulerInstanceId</span><span class="token punctuation">}</span></span><span class="token string"> since </span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">fire<span class="token punctuation">.</span>FireTimeUtc</span><span class="token format-string"><span class="token punctuation">:</span>O</span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>A <code>FireInstance</code> carries <code>FireInstanceId</code>, <code>TriggerKey</code>, <code>JobKey</code>, <code>SchedulerInstanceId</code>, <code>State</code>, <code>FireTimeUtc</code>, <code>ScheduledFireTimeUtc</code> and <code>ExecutionGroup</code>.</p><p><code>State</code> is a <code>FireInstanceState</code> — <code>Acquired</code> or <code>Executing</code> — and it is the one filter in the whole family with a <strong>non-null default</strong>. A <code>FireInstanceQuery</code> that says nothing about state lists what is running, because that is the question the query is usually asked. Set <code>State = null</code> to include firings that a node has reserved but not yet started:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">FireInstanceQuery</span> reservedAndRunning <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> State <span class="token operator">=</span> <span class="token keyword">null</span> <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">FireInstanceQuery</span> reservedOnly <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> State <span class="token operator">=</span> FireInstanceState<span class="token punctuation">.</span>Acquired <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>JobKey</code> is nullable for the same reason: an <code>Acquired</code> firing has not resolved its job yet. That also means a query filtered by <code>Job</code> never matches a reservation, so combining <code>Job</code> with <code>State = null</code> still lists executing firings only.</p><p>Ordering adds a third key here. Group and name do not order a page deterministically when one trigger has several firings in flight, so firings are ordered by trigger group, then trigger name, then fire instance id.</p><h3 id="three-caveats-for-any-ui-built-over-this" tabindex="-1"><a class="header-anchor" href="#three-caveats-for-any-ui-built-over-this"><span>Three caveats for any UI built over this</span></a></h3><ul><li><strong>A vetoed firing does not linger.</strong> Applying an <code>ITriggerListener</code> veto completes the firing. It can be listed for the instant between the store recording it and the veto being decided, and never after — so a &quot;running jobs&quot; screen cannot be used to count vetoes.</li><li><strong>Elapsed time can come out negative.</strong> It is your clock minus <code>FireTimeUtc</code>, and <code>FireTimeUtc</code> was written by the firing node&#39;s clock. On a cluster with skewed clocks the difference can be below zero; clamp it.</li><li><strong><code>ScheduledFireTimeUtc</code> is not the missed time.</strong> It is the schedule as the owning node recorded it, which after a misfire is the <em>rescheduled</em> time. The gap between it and <code>FireTimeUtc</code> is not misfire lateness.</li></ul><p>To stop one of them, <code>InterruptFireInstance(fireInstanceId)</code> targets a single firing where <code>Interrupt(jobKey)</code> stops every execution of that job.</p><h2 id="group-pause-state" tabindex="-1"><a class="header-anchor" href="#group-pause-state"><span>Group pause state</span></a></h2><p><code>TriggerGroup.Paused</code> is real: the stores persist trigger group pause state, so <code>QueryTriggerGroups(new TriggerGroupQuery { Paused = true })</code> is the replacement for <code>GetPausedTriggerGroups()</code>, and <code>new TriggerGroupQuery { Name = NameMatcher.NameEquals(&quot;reporting&quot;), Take = 1 }</code> answers &quot;is this one group paused?&quot; without listing the rest. The other three comparisons list a tenant&#39;s or a subsystem&#39;s groups the same way: <code>NameMatcher.NameStartsWith(&quot;tenant-42-&quot;)</code>.</p>`,24),e(`p`,null,[l[9]||=e(`code`,null,`JobGroup.Paused`,-1),l[10]||=r(` works the same way, and on both stores: 4.x records paused job groups in `,-1),l[11]||=e(`code`,null,`QRTZ_PAUSED_JOB_GRPS`,-1),l[12]||=r(`, so `,-1),l[13]||=e(`code`,null,`QueryJobGroups(new JobGroupQuery { Paused = true })`,-1),l[14]||=r(` is a real listing and `,-1),l[15]||=e(`code`,null,`new JobGroupQuery { Name = NameMatcher.NameEquals("reporting"), Take = 1 }`,-1),l[16]||=r(` answers for one group. On 3.x this was the one thing the ADO store could not report — `,-1),l[17]||=e(`code`,null,`IsJobGroupPaused`,-1),l[18]||=r(` answered `,-1),l[19]||=e(`code`,null,`false`,-1),l[20]||=r(` for every group there — which is why the `,-1),c(m,{to:`/documentation/database/schema-changes.html#version-4-0`},{default:i(()=>[...l[8]||=[r(`4.0 schema migration`,-1)]]),_:1}),l[21]||=r(` is mandatory even for a database that took every optional 3.x migration.`,-1)]),l[33]||=t(`<p>A group can be paused while it holds nothing, and <code>Paused = true</code> reports such a group. The unfiltered listing does not, because it enumerates the groups jobs and triggers are actually in — so a group with no members appears in the paused listing alone, which is the only place a caller can find it in order to resume it.</p><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Pausing an empty <em>trigger</em> group also pauses the triggers added to it afterwards. A paused <em>job</em> group does that only in the in-memory store; the ADO store pauses the triggers of the jobs in the group when the pause runs, and records the group, but does not impose the pause on jobs added later.</p></div><p>Pausing and resuming by matcher is a <em>group</em> operation — it records the group as paused, which is what catches the triggers added to it afterwards — so it is named for groups and answers with their names, where the key-set <code>PauseTriggers(keys)</code> answers with the keys it moved:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">List<span class="token punctuation">&lt;</span><span class="token keyword">string</span><span class="token punctuation">&gt;</span></span> pausedGroups <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">PauseTriggerGroups</span><span class="token punctuation">(</span></span>
<span class="line">    GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupStartsWith</span><span class="token punctuation">(</span><span class="token string">&quot;nightly-&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="a-worked-example-an-admin-list-screen" tabindex="-1"><a class="header-anchor" href="#a-worked-example-an-admin-list-screen"><span>A worked example: an admin list screen</span></a></h2><p>Page size, a state filter, a total for the pager, and full detail only for the row that was opened:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">TriggerListModel</span><span class="token punctuation">(</span><span class="token class-name">IScheduler</span> scheduler<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">async</span> <span class="token return-type class-name">Task<span class="token punctuation">&lt;</span><span class="token punctuation">(</span>IReadOnlyList<span class="token punctuation">&lt;</span>TriggerHeader<span class="token punctuation">&gt;</span> Rows<span class="token punctuation">,</span> <span class="token keyword">int</span> Total<span class="token punctuation">)</span><span class="token punctuation">&gt;</span></span> <span class="token function">GetPage</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token class-name"><span class="token keyword">int</span></span> pageNumber<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name"><span class="token keyword">int</span></span> pageSize<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">TriggerState<span class="token punctuation">?</span></span> state<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name"><span class="token keyword">string</span><span class="token punctuation">?</span></span> groupPrefix<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">TriggerQuery</span> query <span class="token operator">=</span> <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            Skip <span class="token operator">=</span> <span class="token punctuation">(</span>pageNumber <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">*</span> pageSize<span class="token punctuation">,</span></span>
<span class="line">            Take <span class="token operator">=</span> pageSize<span class="token punctuation">,</span></span>
<span class="line">            IncludeTotalCount <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">            State <span class="token operator">=</span> state<span class="token punctuation">,</span></span>
<span class="line">            Group <span class="token operator">=</span> groupPrefix <span class="token keyword">is</span> <span class="token keyword">null</span></span>
<span class="line">                <span class="token punctuation">?</span> <span class="token keyword">null</span></span>
<span class="line">                <span class="token punctuation">:</span> GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupStartsWith</span><span class="token punctuation">(</span>groupPrefix<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>TriggerHeader<span class="token punctuation">&gt;</span></span> page <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryTriggers</span><span class="token punctuation">(</span>query<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token punctuation">(</span>page<span class="token punctuation">.</span>Items<span class="token punctuation">,</span> page<span class="token punctuation">.</span>TotalCount <span class="token operator">??</span> page<span class="token punctuation">.</span>Items<span class="token punctuation">.</span>Count<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">public</span> <span class="token return-type class-name">ValueTask<span class="token punctuation">&lt;</span>List<span class="token punctuation">&lt;</span>ITrigger<span class="token punctuation">&gt;</span><span class="token punctuation">&gt;</span></span> <span class="token function">Expand</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token class-name">IReadOnlyCollection<span class="token punctuation">&lt;</span>TriggerKey<span class="token punctuation">&gt;</span></span> keys<span class="token punctuation">,</span></span>
<span class="line">        <span class="token class-name">CancellationToken</span> cancellationToken<span class="token punctuation">)</span> <span class="token operator">=&gt;</span></span>
<span class="line">        scheduler<span class="token punctuation">.</span><span class="token function">GetTriggers</span><span class="token punctuation">(</span>keys<span class="token punctuation">,</span> cancellationToken<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Nothing here loops over keys, and nothing loads a <code>JobDataMap</code> the list does not show.</p><h2 id="the-preset-and-the-mutation-beside-it" tabindex="-1"><a class="header-anchor" href="#the-preset-and-the-mutation-beside-it"><span>The preset, and the mutation beside it</span></a></h2><p>Reading has two altitudes on purpose. The <code>Query*</code> members take a record — a filter, a page, an optional count — and the <code>Get*</code> conveniences above answer the questions that need none of that. Neither is the other&#39;s leftovers, and a third thing is deliberately missing: a shorthand that saves only the <code>new</code>. <code>QueryJobs(new JobQuery())</code> is not worth an overload, because the record it names is the point of the query API.</p><p>What does earn a name is a <em>preset</em> — one that knows a filter you would otherwise have to look up. There is one, and it pages exactly as the member does — the first <code>PagedQuery.DefaultTake</code> items, with <code>HasMore</code> reporting the rest:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>JobHeader<span class="token punctuation">&gt;</span></span> jobs <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryJobs</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">JobQuery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>TriggerHeader<span class="token punctuation">&gt;</span></span> triggers <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryTriggers</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">TriggerQuery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>FireInstance<span class="token punctuation">&gt;</span></span> running <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryFireInstances</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">FireInstanceQuery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>FireInstance<span class="token punctuation">&gt;</span></span> runningOneJob <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryFireInstances</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">FireInstanceQuery</span> <span class="token punctuation">{</span> Job <span class="token operator">=</span> jobKey <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// the one shorthand that is a preset rather than a synonym: it knows the filter</span></span>
<span class="line"><span class="token class-name">PagedResult<span class="token punctuation">&lt;</span>TriggerHeader<span class="token punctuation">&gt;</span></span> failed <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">QueryTriggersInError</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Two more sit beside it. Resetting the failed triggers of a group was a listing plus a key-set reset; it is one call on <code>IScheduler</code>, beside the key-set form it is built from:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name">List<span class="token punctuation">&lt;</span>TriggerKey<span class="token punctuation">&gt;</span></span> reset <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">ResetTriggersFromErrorState</span><span class="token punctuation">(</span></span>
<span class="line">    GroupMatcher<span class="token operator">&lt;</span>TriggerKey<span class="token operator">&gt;</span><span class="token punctuation">.</span><span class="token function">GroupEquals</span><span class="token punctuation">(</span><span class="token string">&quot;imports&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>That is still the two calls underneath — a listing filtered by <code>State = TriggerState.Error</code> and the group, then <code>ResetTriggersFromErrorState(keys)</code> — so it is not one atomic operation, and a trigger that fails between them is left for the next call. What resetting a trigger does is unchanged.</p><p>And asking whether a calendar is registered no longer means loading it. <code>GetCalendar</code> deserializes the stored blob to hand you an <code>ICalendar</code> you were going to throw away; <code>Exists</code> asks the store for the name:</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name"><span class="token keyword">bool</span></span> haveHolidays <span class="token operator">=</span> <span class="token keyword">await</span> scheduler<span class="token punctuation">.</span><span class="token function">Exists</span><span class="token punctuation">(</span><span class="token string">&quot;holidays&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="the-compatibility-layer" tabindex="-1"><a class="header-anchor" href="#the-compatibility-layer"><span>The compatibility layer</span></a></h2><p>The old call shapes still compile. <code>SchedulerQueryExtensions</code> puts eight of them back as extension methods on <code>IScheduler</code>:</p><table><thead><tr><th>Extension</th><th>Built on</th></tr></thead><tbody><tr><td><code>GetJobKeys(matcher)</code></td><td><code>QueryJobs</code></td></tr><tr><td><code>GetTriggerKeys(matcher)</code></td><td><code>QueryTriggers</code></td></tr><tr><td><code>GetTriggersOfJob(jobKey)</code></td><td><code>QueryTriggers</code> + <code>GetTriggers</code></td></tr><tr><td><code>GetJobGroupNames()</code></td><td><code>QueryJobGroups</code></td></tr><tr><td><code>GetTriggerGroupNames()</code></td><td><code>QueryTriggerGroups</code></td></tr><tr><td><code>GetPausedTriggerGroups()</code></td><td><code>QueryTriggerGroups</code> with <code>Paused = true</code></td></tr><tr><td><code>GetCalendarNames()</code></td><td><code>QueryCalendarNames</code></td></tr><tr><td><code>IsJobGroupPaused(name)</code> / <code>IsTriggerGroupPaused(name)</code></td><td>the group listings</td></tr></tbody></table><p>They exist so a 3.x port compiles, and each one <strong>enumerates the entire result</strong> — they pass <code>Take = PagedQuery.All</code> deliberately. That is fine for a group-name list and a bad idea for a trigger listing on a busy scheduler. Treat them as a migration aid: anywhere the result can be large, or where the row needs state or fire times, move to the query member.</p><p>One behavioral difference to know about: a null matcher now throws <code>ArgumentNullException</code>. In 3.x <code>GetJobKeys(null)</code> quietly meant &quot;everything&quot;; pass <code>GroupMatcher&lt;JobKey&gt;.AnyGroup()</code> when that is what you meant.</p><h2 id="notes-for-job-store-authors" tabindex="-1"><a class="header-anchor" href="#notes-for-job-store-authors"><span>Notes for job store authors</span></a></h2><p>The six query members are abstract on <code>IJobStore</code>, so a custom store implements them rather than inheriting a default. Three rules keep a store consistent with the shipped ones:</p><ul><li>Order by group then name, ordinal, and add fire instance id as a third key for firings. Paging is meaningless without a total order, and callers rely on this one.</li><li>Read one row past <code>Take</code> to set <code>HasMore</code>, and only run the count query when <code>IncludeTotalCount</code> is set. <code>Take = 0</code> with <code>IncludeTotalCount</code> must skip the row query entirely.</li><li>The bulk fetches are <code>GetJobs(keys)</code> and <code>GetTriggers(keys)</code> on the store — the scheduler&#39;s <code>GetJobDetails</code> is the same operation under the scheduler&#39;s vocabulary.</li></ul>`,25),e(`p`,null,[l[23]||=r(`The `,-1),c(m,{to:`/documentation/quartz-4.x/how-tos/custom-job-store.html`},{default:i(()=>[...l[22]||=[r(`job store how-to`,-1)]]),_:1}),l[24]||=r(` covers the rest of the contract.`,-1)]),l[34]||=e(`h2`,{id:`see-also`,tabindex:`-1`},[e(`a`,{class:`header-anchor`,href:`#see-also`},[e(`span`,null,`See also`)])],-1),e(`ul`,null,[e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/tutorial/more-about-triggers.html`},{default:i(()=>[...l[25]||=[r(`More About Triggers`,-1)]]),_:1}),l[26]||=r(` — what the header fields mean`,-1)]),e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/how-tos/rescheduling-jobs.html`},{default:i(()=>[...l[27]||=[r(`Rescheduling Jobs`,-1)]]),_:1}),l[28]||=r(` — finding triggers in the error state and fixing them`,-1)]),e(`li`,null,[c(m,{to:`/documentation/quartz-4.x/packages/http-api.html`},{default:i(()=>[...l[29]||=[r(`HTTP API`,-1)]]),_:1}),l[30]||=r(` — the same queries over the wire`,-1)])])])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};